use maho_rpc::rpc_client::RpcSocketClient;
use tokio::io::{AsyncReadExt,AsyncWriteExt};
#[tokio::test]async fn close_response_clears_only_matching_lease(){let(client,mut host)=tokio::net::UnixStream::pair().unwrap();let mut client=RpcSocketClient::from_stream(client);client.frames.session_id=Some("selected".into());let serve=async{let mut bytes=vec![];let mut byte=[0];loop{host.read_exact(&mut byte).await.unwrap();bytes.push(byte[0]);if byte[0]==b'\n'{break;}}let request:serde_json::Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(request["type"],"close_session");assert_eq!(request["sessionId"],"other");host.write_all(b"{\"type\":\"response\",\"id\":\"req_1\",\"success\":true}\n").await.unwrap();};let close=client.close_session(Some("other"),|_|{});let(result,())=tokio::time::timeout(std::time::Duration::from_secs(2),async{tokio::join!(close,serve)}).await.unwrap();result.unwrap();assert_eq!(client.frames.session_id.as_deref(),Some("selected"));drop(host);client.close_session(None,|_|{}).await.unwrap();assert!(client.frames.session_id.is_none());}
